    private escapeHtml(value: any): string {
        return String(value ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    private luhnDigit(value: string): number {
        const digits = String(value).split('');
        const refactored: Array<string | number> = [];
        digits.forEach((num, i) => {
            refactored.push(i % 2 === 0 ? num : Number(num) * 2);
        });
        const count = String(refactored.join('')).split('').reduce((sum, digit) => sum + Number(digit), 0);
        const lastDigit = count % 10;
        return lastDigit > 0 ? Math.abs(Math.ceil(count / 10) * 10 - count) : 0;
    }


    private parseTicketTemplate(html: string): string {
        const head = `
        <!DOCTYPE html><html lang="en"><head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <meta http-equiv="X-UA-Compatible" content="ie=edge"> <title></title> <style> @font-face{ font-family: "SST Typewriter"; src: url(data:font/truetype;charset=utf-8;base64,) } body{ font-family: "SST Typewriter"!important; color: #000; } .m-0{ margin:0!important; } .p-0{ padding:0!important; } .mb-0{ margin-bottom: 0px; padding-bottom: 0px; } .mt-0{ margin-top: 0px; padding-bottom: 0px; } .mt-5{ margin-top:5px; } .mb-5{ margin-bottom:5px; } .mt-10{ margin-top:10px; } .mb-10{ margin-bottom:10px; } .pl-10{ padding-left: 10px; } .fw-600{ font-weight: 600; } h1 { font-size: 28px !important; color: #000; margin: 0 0 8px 0; } h4 { font-size: 26px !important; color: #000; } h5 { font-size: 24px !important; color: #000; } p, a, td, small { font-size: 20px !important; color: #000; } table { width: 100%; } img { max-width: 100%; } </style></head><body style="padding-left:5px!important;padding-right:15px!important;">
        `;

        //h4 { font-size: 22px !important; color: #000; } h5 { font-size: 20px !important; color: #000; } p, a, td { font-size: 16px !important; color: #000; }

        const footer = `</body></html>`;
        return head + html + footer;
    }

      // Generate FPN Number
    private generateFpnNumber(oldId: number): string {
        const digits = String(Math.floor(Math.random() * 1_000_000_000)).padStart(10, '0');
        const fpnNumber = (oldId + digits).slice(0, 9);
        return fpnNumber;
    }
